def matter_relationship_detail(matter_id, relationship_id):
    ensure_matter_tables()

    matter, events = get_matter(matter_id)

    if not matter:
        flash("Matter not found.", "warning")
        return redirect(url_for("matters_dashboard"))

    relationship = get_matter_relationship(
        matter_id,
        relationship_id
    )

    if not relationship:
        flash("Matter relationship not found.", "warning")
        return redirect(
            url_for("matter_detail", matter_id=matter_id)
        )

    relationship_type = relationship[2]
    linked_record_id = relationship[3]

    endpoint_map = {
        "Trust": ("trust_detail", {"trust_id": linked_record_id}),
        "Document": (
            "document_detail",
            {"document_id": linked_record_id}
        ),
        "Transfer": (
            "transfer_detail",
            {"transfer_id": linked_record_id}
        ),
        "Media": (
            "media_file",
            {"media_id": linked_record_id}
        ),
        "Minute": (
            "trust_minute_detail",
            {"minute_id": linked_record_id}
        ),
        "Intake Record": (
            "intake_saved_snapshot",
            {"intake_id": linked_record_id}
        ),
    }

    linked_record_url = None
    route_config = endpoint_map.get(relationship_type)

    if route_config:
        endpoint_name, endpoint_values = route_config
        try:
            linked_record_url = url_for(
                endpoint_name,
                **endpoint_values
            )
        except Exception:
            linked_record_url = None

    relationship_audit = (
        build_relationship_audit_summary(
            matter_id,
            relationship_id,
        )
    )

    return render_template(
        "matter_relationship_detail.html",
        matter=matter,
        relationship=relationship,
        linked_record_url=linked_record_url,
        relationship_audit=relationship_audit
    )

